/* The entry for code point c in util.unicodeCaseFoldings, or NULL. */
const MarkFolding *mark_folding_lookup(unsigned long c)
{
    size_t lo = 0;
    size_t hi = MARK_FOLD_COUNT;

    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;

        if (foldings[mid].from == c) return &foldings[mid];
        if (foldings[mid].from < c) lo = mid + 1;
        else hi = mid;
    }
    return NULL;
}
